    val verses: List<Verse> by lazy {
        listOf(
            // ==================== SURAH 97: AL-QADR (5 Verses) ====================
            make(97, "Al-Qadr", 1, "إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ", "<ghunnah>إِنَّا</ghunnah> <madd>أَن</madd><ikhfa>زَلْنَاهُ</ikhfa> فِي لَيْلَةِ <hamzat_wasl>الْ</hamzat_wasl><qalqalah>قَدْرِ</qalqalah>", "Inna anzalnahu fi laylatil-qadr", "Indeed, We sent the Qur'an down during the Night of Decree.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),
            make(97, "Al-Qadr", 2, "وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ", "وَمَا <madd>أَ</madd><qalqalah>دْرَاكَ</qalqalah> مَا لَيْلَةُ <hamzat_wasl>الْ</hamzat_wasl><qalqalah>قَدْرِ</qalqalah>", "Wa ma adraka ma laylatul-qadr", "And what can make you know what is the Night of Decree?", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL)),
            make(97, "Al-Qadr", 3, "لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ", "لَيْلَةُ <hamzat_wasl>الْ</hamzat_wasl><qalqalah>قَدْرِ</qalqalah> خَيْرٌ <idgham>مِّنْ</idgham> أَلْفِ شَهْرٍ", "Laylatul-qadri khayrum min alfi shahr", "The Night of Decree is better than a thousand months.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH, TajweedRuleType.IDGHAM)),
            make(97, "Al-Qadr", 4, "تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ", "تَنَزَّلُ <hamzat_wasl>الْ</hamzat_wasl>مَلَ<madd>ائِكَةُ</madd> وَ<hamzat_wasl>ال</hamzat_wasl>رُّوحُ فِيهَا بِإِذْنِ رَبِّهِم <idgham>مِّن</idgham> <ikhfa>كُلِّ</ikhfa> أَمْرٍ", "Tanazzalul-mala'ikatu war-ruhu fiha bi-idhni rabbihim min kulli amr", "The angels and the Spirit descend therein by permission of their Lord for every matter.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.IDGHAM, TajweedRuleType.GHUNNAH)),
            make(97, "Al-Qadr", 5, "سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ", "سَلَامٌ هِيَ حَتَّىٰ مَ<tafkhim>طْ</tafkhim><qalqalah>لَعِ</qalqalah> <hamzat_wasl>الْ</hamzat_wasl><qalqalah>فَجْرِ</qalqalah>", "Salamun hiya hatta matla'il-fajr", "Peace it is until the emergence of dawn.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL)),

            // ==================== SURAH 98: AL-BAYYINAH (8 Verses) ====================
            make(98, "Al-Bayyinah", 1, "لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ الْبَيِّنَةُ", "لَمْ يَكُنِ <hamzat_wasl>الَّذِينَ</hamzat_wasl> كَفَرُوا مِنْ أَهْلِ <hamzat_wasl>الْ</hamzat_wasl>كِتَابِ وَ<hamzat_wasl>الْ</hamzat_wasl>مُشْرِكِينَ مُن<ikhfa>فَكِّينَ</ikhfa> حَتَّىٰ تَأْتِيَهُمُ <hamzat_wasl>الْ</hamzat_wasl>بَيِّنَةُ", "Lam yakunil-ladhina kafaru min ahlil-kitabi wal-mushrikina munfakkina hatta ta'tiyahumul-bayyinah", "Those who disbelieved among the People of the Scripture and the polytheists were not to be parted [from misbelief] until there came to them clear evidence -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(98, "Al-Bayyinah", 2, "رَسُولٌ مِّنَ اللَّهِ يَتْلُو صُحُفًا مُّطَهَّرَةً", "رَسُولٌ <idgham>مِّنَ</idgham> <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهِ</tafkhim> يَتْلُو <tafkhim>صُحُفًا</tafkhim> <idgham>مُّطَهَّرَةً</idgham>", "Rasulum minal-lahi yatlu suhufam mutahharah", "A Messenger from Allah, reciting purified scriptures", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(98, "Al-Bayyinah", 3, "فِيهَا كُتُبٌ قَيِّمَةٌ", "فِيهَا كُتُبٌ <ikhfa><tafkhim>قَيِّمَةٌ</tafkhim></ikhfa>", "Fiha kutubun qayyimah", "Within which are correct writings.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(98, "Al-Bayyinah", 4, "وَمَا تَفَرَّقَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَةُ", "وَمَا تَفَرَّ<tafkhim>قَ</tafkhim> <hamzat_wasl>الَّذِينَ</hamzat_wasl> <madd>أُوتُوا</madd> <hamzat_wasl>الْ</hamzat_wasl>كِتَابَ إِلَّا مِن <iqlab>بَعْدِ</iqlab> مَا <madd>جَاءَتْهُمُ</madd> <hamzat_wasl>الْ</hamzat_wasl>بَيِّنَةُ", "Wa ma tafarraqal-ladhina utul-kitaba illa mim ba'di ma ja'at-humul-bayyinah", "Nor did those who were given the Scripture become divided until after there had come to them clear evidence.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.IQLAB)),
            make(98, "Al-Bayyinah", 5, "وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ۚ وَذَٰلِكَ دِينُ الْقَيِّمَةِ", "وَمَا <madd>أُمِرُوا</madd> إِلَّا لِيَعْبُدُوا <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهَ</tafkhim> مُخْلِصِينَ لَهُ <hamzat_wasl>ال</hamzat_wasl>دِّينَ حُنَفَ<madd>اءَ</madd> وَيُ<tafkhim>قِيمُوا</tafkhim> <hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّلَاةَ</tafkhim> وَيُؤْتُوا <hamzat_wasl>ال</hamzat_wasl>زَّكَاةَ ۚ وَذَٰلِكَ دِينُ <hamzat_wasl>الْ</hamzat_wasl><tafkhim>قَيِّمَةِ</tafkhim>", "Wa ma umiru illa liya'budul-laha mukhlisina lahud-dina hunafa'a wa yuqimus-salata wa yu'tuz-zakah, wa dhalika dinul-qayyimah", "And they were not commanded except to worship Allah, [being] sincere to Him in religion, inclining to truth, and to establish prayer and to give zakah. And that is the correct religion.", listOf(TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(98, "Al-Bayyinah", 6, "إِنَّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ فِي نَارِ جَهَنَّمَ خَالِدِينَ فِيهَا ۚ أُولَٰئِكَ هُمْ شَرُّ الْبَرِيَّةِ", "<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الَّذِينَ</hamzat_wasl> كَفَرُوا مِنْ أَهْلِ <hamzat_wasl>الْ</hamzat_wasl>كِتَابِ وَ<hamzat_wasl>الْ</hamzat_wasl>مُشْرِكِينَ فِي نَارِ <ghunnah>جَهَنَّمَ</ghunnah> خَالِدِينَ فِيهَا ۚ أُو<madd>لَٰئِكَ</madd> هُمْ شَرُّ <hamzat_wasl>الْ</hamzat_wasl>بَرِيَّةِ", "Innal-ladhina kafaru min ahlil-kitabi wal-mushrikina fi nari jahannama khalidina fiha, ula'ika hum sharrul-bariyyah", "Indeed, they who disbelieved among the People of the Scripture and the polytheists will be in the fire of Hell, abiding eternally therein. Those are the worst of creatures.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD)),
            make(98, "Al-Bayyinah", 7, "إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ هُمْ خَيْرُ الْبَرِيَّةِ", "<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الَّذِينَ</hamzat_wasl> <madd>آمَنُوا</madd> وَعَمِلُوا <hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّالِحَاتِ</tafkhim> أُو<madd>لَٰئِكَ</madd> هُمْ خَيْرُ <hamzat_wasl>الْ</hamzat_wasl>بَرِيَّةِ", "Innal-ladhina amanu wa 'amilus-salihati ula'ika hum khayrul-bariyyah", "Indeed, they who have believed and done righteous deeds - those are the best of creatures.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM)),
            make(98, "Al-Bayyinah", 8, "جَزَاؤُهُمْ عِندَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ۖ رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِيَ رَبَّهُ", "<madd>جَزَاؤُهُمْ</madd> عِن<ikhfa>دَ</ikhfa> رَبِّهِمْ <ghunnah>جَنَّاتُ</ghunnah> عَدْنٍ <ikhfa><qalqalah>تَجْرِي</qalqalah></ikhfa> مِن <ikhfa>تَحْتِهَا</ikhfa> <hamzat_wasl>الْ</hamzat_wasl>أَنْهَارُ خَالِدِينَ فِيهَا <madd>أَبَدًا</madd> ۖ <tafkhim>رَّضِيَ</tafkhim> <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> عَنْهُمْ وَ<tafkhim>رَضُوا</tafkhim> عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِيَ رَبَّهُ", "Jaza'uhum 'inda rabbihim jannatu 'adnin tajri min tahtihal-anharu khalidina fiha abada, radiyal-lahu 'anhum wa radu 'anh, dhalika liman khashiya rabbah", "Their reward with their Lord will be gardens of perpetual residence beneath which rivers flow, wherein they will abide forever, Allah being well pleased with them and they with Him. That is for whoever has feared his Lord.", listOf(TajweedRuleType.MADD, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),

            // ==================== SURAH 99: AZ-ZALZALAH (8 Verses) ====================
            make(99, "Az-Zalzalah", 1, "إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا", "إِذَا زُلْزِلَتِ <hamzat_wasl>الْ</hamzat_wasl>أَرْضُ زِلْزَالَهَا", "Idha zulzilatil-ardu zilzalaha", "When the earth is shaken with its [final] earthquake", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(99, "Az-Zalzalah", 2, "وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا", "وَأَخْرَجَتِ <hamzat_wasl>الْ</hamzat_wasl>أَرْضُ أَثْ<tafkhim><qalqalah>قَالَهَا</qalqalah></tafkhim>", "Wa akhrajatil-ardu athqalaha", "And the earth discharges its burdens", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(99, "Az-Zalzalah", 3, "وَقَالَ الْإِنسَانُ مَا لَهَا", "وَ<tafkhim>قَالَ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانُ</ikhfa> مَا لَهَا", "Wa qalal-insanu ma laha", "And man says, 'What is [wrong] with it?' -", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(99, "Az-Zalzalah", 4, "يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا", "يَوْمَئِذٍ <ikhfa>تُحَدِّثُ</ikhfa> أَخْبَارَهَا", "Yawma'idhin tuhaddithu akhbaraha", "That Day, it will report its news", listOf(TajweedRuleType.GHUNNAH)),
            make(99, "Az-Zalzalah", 5, "بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا", "بِ<ghunnah>أَنَّ</ghunnah> رَبَّكَ أَوْحَىٰ لَهَا", "Bi-anna rabbaka awha laha", "Because your Lord has inspired it.", listOf(TajweedRuleType.GHUNNAH)),
            make(99, "Az-Zalzalah", 6, "يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا لِّيُرَوْا أَعْمَالَهُمْ", "يَوْمَئِذٍ <idgham>يَ<tafkhim>صْدُرُ</tafkhim></idgham> <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاسُ</ghunnah> أَشْتَاتًا <idgham>لِّيُرَوْا</idgham> أَعْمَالَهُمْ", "Yawma'idhiy yasdurun-nasu ashtatal liyuraw a'malahum", "That Day, the people will proceed in scattered groups to be shown [the result of] their deeds.", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(99, "Az-Zalzalah", 7, "فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ", "فَمَن <idgham>يَعْمَلْ</idgham> مِثْ<tafkhim><qalqalah>قَالَ</qalqalah></tafkhim> ذَرَّةٍ خَيْرًا <idgham>يَرَهُ</idgham>", "Famay ya'mal mithqala dharratin khayray yarah", "So whoever does an atom's weight of good will see it,", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM)),
            make(99, "Az-Zalzalah", 8, "وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ", "وَمَن <idgham>يَعْمَلْ</idgham> مِثْ<tafkhim><qalqalah>قَالَ</qalqalah></tafkhim> ذَرَّةٍ شَرًّا <idgham>يَرَهُ</idgham>", "Wa may ya'mal mithqala dharratin sharray yarah", "And whoever does an atom's weight of evil will see it.", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM)),

            // ==================== SURAH 100: AL-'ADIYAT (11 Verses) ====================
            make(100, "Al-'Adiyat", 1, "وَالْعَادِيَاتِ ضَبْحًا", "وَ<hamzat_wasl>الْ</hamzat_wasl>عَادِيَاتِ <tafkhim>ضَ</tafkhim><qalqalah>بْحًا</qalqalah>", "Wal-'adiyati dabha", "By the racers, panting,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(100, "Al-'Adiyat", 2, "فَالْمُورِيَاتِ قَدْحًا", "فَ<hamzat_wasl>الْ</hamzat_wasl>مُورِيَاتِ <tafkhim><qalqalah>قَدْحًا</qalqalah></tafkhim>", "Fal-muriyati qadha", "And the producers of sparks [when] striking", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(100, "Al-'Adiyat", 3, "فَالْمُغِيرَاتِ صُبْحًا", "فَ<hamzat_wasl>الْ</hamzat_wasl>مُغِيرَاتِ <tafkhim>صُ</tafkhim><qalqalah>بْحًا</qalqalah>", "Fal-mughirati subha", "And the chargers at dawn,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(100, "Al-'Adiyat", 4, "فَأَثَرْنَ بِهِ نَقْعًا", "فَأَثَرْنَ بِهِ <tafkhim>نَ</tafkhim><qalqalah>قْ</qalqalah>عًا", "Fa-atharna bihi naq'a", "Stirring up thereby [clouds of] dust,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(100, "Al-'Adiyat", 5, "فَوَسَطْنَ بِهِ جَمْعًا", "فَوَسَ<tafkhim><qalqalah>طْ</qalqalah></tafkhim>نَ بِهِ جَمْعًا", "Fawasatna bihi jam'a", "Arriving thereby in the center collectively,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(100, "Al-'Adiyat", 6, "إِنَّ الْإِنسَانَ لِرَبِّهِ لَكَنُودٌ", "<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانَ</ikhfa> لِرَبِّهِ لَكَنُودٌ", "Innal-insana lirabbihi lakanud", "Indeed mankind, to his Lord, is ungrateful.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(100, "Al-'Adiyat", 7, "وَإِنَّهُ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ", "وَ<ghunnah>إِنَّهُ</ghunnah> عَلَىٰ ذَٰلِكَ لَشَهِيدٌ", "Wa innahu 'ala dhalika lashahid", "And indeed, he to that is a witness.", listOf(TajweedRuleType.GHUNNAH)),
            make(100, "Al-'Adiyat", 8, "وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ", "وَ<ghunnah>إِنَّهُ</ghunnah> لِحُبِّ <hamzat_wasl>الْ</hamzat_wasl>خَيْرِ لَشَدِيدٌ", "Wa innahu lihubbil-khayri lashadid", "And indeed he is, in love of wealth, intense.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(100, "Al-'Adiyat", 9, "أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِي الْقُبُورِ", "أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِي <hamzat_wasl>الْ</hamzat_wasl><tafkhim>قُبُورِ</tafkhim>", "Afala ya'lamu idha bu'thira ma fil-qubur", "But does he not know that when the contents of the graves are scattered", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(100, "Al-'Adiyat", 10, "وَحُصِّلَ مَا فِي الصُّدُورِ", "وَحُ<tafkhim>صِّلَ</tafkhim> مَا فِي <hamzat_wasl>ال</hamzat_wasl><tafkhim>صُّدُورِ</tafkhim>", "Wa hussila ma fis-sudur", "And that within the breasts is made apparent,", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(100, "Al-'Adiyat", 11, "إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌ", "<ghunnah>إِنَّ</ghunnah> رَبَّهُم <ikhfa>بِهِمْ</ikhfa> يَوْمَئِذٍ <idgham>لَّخَبِيرٌ</idgham>", "Inna rabbahum bihim yawma'idhil lakhabir", "Indeed, their Lord with them, that Day, is [fully] Acquainted.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.IDGHAM)),

            // ==================== SURAH 101: AL-QARI'AH (11 Verses) ====================
            make(101, "Al-Qari'ah", 1, "الْقَارِعَةُ", "<hamzat_wasl>الْ</hamzat_wasl><tafkhim>قَارِعَةُ</tafkhim>", "Al-qari'ah", "The Striking Calamity -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(101, "Al-Qari'ah", 2, "مَا الْقَارِعَةُ", "مَا <hamzat_wasl>الْ</hamzat_wasl><tafkhim>قَارِعَةُ</tafkhim>", "Mal-qari'ah", "What is the Striking Calamity?", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(101, "Al-Qari'ah", 3, "وَمَا أَدْرَاكَ مَا الْقَارِعَةُ", "وَمَا <madd>أَ</madd><qalqalah>دْرَاكَ</qalqalah> مَا <hamzat_wasl>الْ</hamzat_wasl><tafkhim>قَارِعَةُ</tafkhim>", "Wa ma adraka mal-qari'ah", "And what can make you know what is the Striking Calamity?", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(101, "Al-Qari'ah", 4, "يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ", "يَوْمَ يَكُونُ <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاسُ</ghunnah> كَ<hamzat_wasl>الْ</hamzat_wasl>فَرَاشِ <hamzat_wasl>الْ</hamzat_wasl>مَ<qalqalah>بْثُوثِ</qalqalah>", "Yawma yakunun-nasu kal-farashil-mabthuth", "It is the Day when people will be like moths, dispersed,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(101, "Al-Qari'ah", 5, "وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنفُوشِ", "وَتَكُونُ <hamzat_wasl>الْ</hamzat_wasl>جِبَالُ كَ<hamzat_wasl>الْ</hamzat_wasl>عِهْنِ <hamzat_wasl>الْ</hamzat_wasl>مَن<ikhfa>فُوشِ</ikhfa>", "Wa takunul-jibalu kal-'ihnil-manfush", "And the mountains will be like wool, fluffed up.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(101, "Al-Qari'ah", 6, "فَأَمَّا مَن ثَقُلَتْ مَوَازِينُهُ", "فَ<ghunnah>أَمَّا</ghunnah> مَن <ikhfa>ثَ<tafkhim>قُلَتْ</tafkhim></ikhfa> مَوَازِينُهُ", "Fa-amma man thaqulat mawazinuh", "Then as for one whose scales are heavy [with good deeds],", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(101, "Al-Qari'ah", 7, "فَهُوَ فِي عِيشَةٍ رَّاضِيَةٍ", "فَهُوَ فِي عِيشَةٍ <idgham><tafkhim>رَّاضِيَةٍ</tafkhim></idgham>", "Fahuwa fi 'ishatir radiyah", "He will be in a pleasant life.", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM)),
            make(101, "Al-Qari'ah", 8, "وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ", "وَ<ghunnah>أَمَّا</ghunnah> مَنْ خَفَّتْ مَوَازِينُهُ", "Wa amma man khaffat mawazinuh", "But as for one whose scales are light,", listOf(TajweedRuleType.GHUNNAH)),
            make(101, "Al-Qari'ah", 9, "فَأُمُّهُ هَاوِيَةٌ", "فَ<ghunnah>أُمُّهُ</ghunnah> هَاوِيَةٌ", "Fa-ummuhu hawiyah", "His refuge will be an abyss.", listOf(TajweedRuleType.GHUNNAH)),
            make(101, "Al-Qari'ah", 10, "وَمَا أَدْرَاكَ مَا هِيَهْ", "وَمَا <madd>أَ</madd><qalqalah>دْرَاكَ</qalqalah> مَا هِيَهْ", "Wa ma adraka ma hiyah", "And what can make you know what that is?", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH)),
            make(101, "Al-Qari'ah", 11, "نَارٌ حَامِيَةٌ", "نَارٌ حَامِيَةٌ", "Narun hamiyah", "It is a Fire, intensely hot.", emptyList()),

            // ==================== SURAH 102: AT-TAKATHUR (8 Verses) ====================
            make(102, "At-Takathur", 1, "أَلْهَاكُمُ التَّكَاثُرُ", "أَلْهَاكُمُ <hamzat_wasl>ال</hamzat_wasl>تَّكَاثُرُ", "Alhakumut-takathur", "Competition in [worldly] increase diverts you", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(102, "At-Takathur", 2, "حَتَّىٰ زُرْتُمُ الْمَقَابِرَ", "حَتَّىٰ زُرْتُمُ <hamzat_wasl>الْ</hamzat_wasl>مَ<tafkhim><qalqalah>قَابِرَ</qalqalah></tafkhim>", "Hatta zurtumul-maqabir", "Until you visit the graveyards.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(102, "At-Takathur", 3, "كَلَّا سَوْفَ تَعْلَمُونَ", "كَلَّا سَوْفَ تَعْلَمُونَ", "Kalla sawfa ta'lamun", "No! You are going to know.", emptyList()),
            make(102, "At-Takathur", 4, "ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ", "<ghunnah>ثُمَّ</ghunnah> كَلَّا سَوْفَ تَعْلَمُونَ", "Thumma kalla sawfa ta'lamun", "Then no! You are going to know.", listOf(TajweedRuleType.GHUNNAH)),
            make(102, "At-Takathur", 5, "كَلَّا لَوْ تَعْلَمُونَ عِلْمَ الْيَقِينِ", "كَلَّا لَوْ تَعْلَمُونَ عِلْمَ <hamzat_wasl>الْ</hamzat_wasl>يَ<tafkhim>قِينِ</tafkhim>", "Kalla law ta'lamuna 'ilmal-yaqin", "No! If you only knew with knowledge of certainty...", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(102, "At-Takathur", 6, "لَتَرَوُنَّ الْجَحِيمَ", "لَتَرَوُ<ghunnah>نَّ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>جَحِيمَ", "Latarawunnal-jahim", "You will surely see the Hellfire.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(102, "At-Takathur", 7, "ثُمَّ لَتَرَوُنَّهَا عَيْنَ الْيَقِينِ", "<ghunnah>ثُمَّ</ghunnah> لَتَرَوُ<ghunnah>نَّهَا</ghunnah> عَيْنَ <hamzat_wasl>الْ</hamzat_wasl>يَ<tafkhim>قِينِ</tafkhim>", "Thumma latarawunnaha 'aynal-yaqin", "Then you will surely see it with the eye of certainty.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(102, "At-Takathur", 8, "ثُمَّ لَتُسْأَلُنَّ يَوْمَئِذٍ عَنِ النَّعِيمِ", "<ghunnah>ثُمَّ</ghunnah> لَتُسْأَلُ<ghunnah>نَّ</ghunnah> يَوْمَئِذٍ عَنِ <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّعِيمِ</ghunnah>", "Thumma latus'alunna yawma'idhin 'anin-na'im", "Then you will surely be asked that Day about pleasure.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),

            // ==================== SURAH 103: AL-'ASR (3 Verses) ====================
            make(103, "Al-'Asr", 1, "وَالْعَصْرِ", "وَ<hamzat_wasl>الْ</hamzat_wasl><tafkhim>عَصْرِ</tafkhim>", "Wal-'asr", "By time,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(103, "Al-'Asr", 2, "إِنَّ الْإِنسَانَ لَفِي خُسْرٍ", "<ghunnah>إِنَّ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl>إِ<ikhfa>نسَانَ</ikhfa> لَفِي خُسْرٍ", "Innal-insana lafi khusr", "Indeed, mankind is in loss,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(103, "Al-'Asr", 3, "إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ", "إِلَّا <hamzat_wasl>الَّذِينَ</hamzat_wasl> <madd>آمَنُوا</madd> وَعَمِلُوا <hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّالِحَاتِ</tafkhim> وَتَوَاصَوْا بِ<hamzat_wasl>الْ</hamzat_wasl><qalqalah>حَقِّ</qalqalah> وَتَوَاصَوْا بِ<hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّ</tafkhim><qalqalah>بْ</qalqalah>رِ", "Illal-ladhina amanu wa 'amilus-salihati wa tawasaw bil-haqqi wa tawasaw bis-sabr", "Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),

            // ==================== SURAH 104: AL-HUMAZAH (9 Verses) ====================
            make(104, "Al-Humazah", 1, "وَيْلٌ لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ", "وَيْلٌ <idgham>لِّكُلِّ</idgham> هُمَزَةٍ <idgham>لُّمَزَةٍ</idgham>", "Waylul likulli humazatil lumazah", "Woe to every scorner and mocker", listOf(TajweedRuleType.IDGHAM)),
            make(104, "Al-Humazah", 2, "الَّذِي جَمَعَ مَالًا وَعَدَّدَهُ", "<hamzat_wasl>الَّذِي</hamzat_wasl> جَمَعَ مَالًا <idgham>وَعَدَّدَهُ</idgham>", "Alladhi jama'a malaw wa 'addadah", "Who collects wealth and [continuously] counts it.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.IDGHAM)),
            make(104, "Al-Humazah", 3, "يَحْسَبُ أَنَّ مَالَهُ أَخْلَدَهُ", "يَحْسَبُ <ghunnah>أَنَّ</ghunnah> مَالَهُ <madd>أَخْلَدَهُ</madd>", "Yahsabu anna malahu akhladah", "He thinks that his wealth will make him immortal.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD)),
            make(104, "Al-Humazah", 4, "كَلَّا ۖ لَيُنبَذَنَّ فِي الْحُطَمَةِ", "كَلَّا ۖ لَ<iqlab>يُن<ghunnah>بَذَنَّ</ghunnah></iqlab> فِي <hamzat_wasl>الْ</hamzat_wasl>حُ<tafkhim>طَمَةِ</tafkhim>", "Kalla layumbadhanna fil-hutamah", "No! He will surely be thrown into the Crusher.", listOf(TajweedRuleType.IQLAB, TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(104, "Al-Humazah", 5, "وَمَا أَدْرَاكَ مَا الْحُطَمَةُ", "وَمَا <madd>أَ</madd><qalqalah>دْرَاكَ</qalqalah> مَا <hamzat_wasl>الْ</hamzat_wasl>حُ<tafkhim>طَمَةُ</tafkhim>", "Wa ma adraka mal-hutamah", "And what can make you know what is the Crusher?", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(104, "Al-Humazah", 6, "نَارُ اللَّهِ الْمُوقَدَةُ", "نَارُ <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهِ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>مُوقَدَةُ", "Narul-lahil-muqadah", "It is the fire of Allah, [eternally] fueled,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(104, "Al-Humazah", 7, "الَّتِي تَطَّلِعُ عَلَى الْأَفْئِدَةِ", "<hamzat_wasl>الَّتِي</hamzat_wasl> <tafkhim>تَطَّلِعُ</tafkhim> عَلَى <hamzat_wasl>الْ</hamzat_wasl>أَفْئِدَةِ", "Allati tattali'u 'alal-af'idah", "Which mounts directed at the hearts.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM)),
            make(104, "Al-Humazah", 8, "إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌ", "<ghunnah>إِنَّهَا</ghunnah> عَلَيْهِم <idgham>مُّؤْ</idgham><tafkhim>صَدَةٌ</tafkhim>", "Innaha 'alayhim mu'sadah", "Indeed, Hellfire will be closed down upon them", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM)),
            make(104, "Al-Humazah", 9, "فِي عَمَدٍ مُّمَدَّدَةٍ", "فِي عَمَدٍ <idgham>مُّمَدَّدَةٍ</idgham>", "Fi 'amadim mumaddadah", "In extended columns.", listOf(TajweedRuleType.IDGHAM)),

            // ==================== SURAH 105: AL-FIL (5 Verses) ====================
            make(105, "Al-Fil", 1, "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ الْفِيلِ", "أَلَمْ تَرَ كَيْفَ فَعَلَ رَبُّكَ بِأَصْحَابِ <hamzat_wasl>الْ</hamzat_wasl>فِيلِ", "Alam tara kayfa fa'ala rabbuka bi-ashabil-fil", "Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(105, "Al-Fil", 2, "أَلَمْ يَجْعَلْ كَيْدَهُمْ فِي تَضْلِيلٍ", "أَلَمْ <qalqalah>يَجْ</qalqalah>عَلْ كَيْدَهُمْ فِي <tafkhim>تَضْلِيلٍ</tafkhim>", "Alam yaj'al kaydahum fi tadlil", "Did He not make their plan into misguidance?", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.TAFKHIM)),
            make(105, "Al-Fil", 3, "وَأَرْسَلَ عَلَيْهِمْ طَيْرًا أَبَابِيلَ", "وَأَرْسَلَ عَلَيْهِمْ <tafkhim>طَيْرًا</tafkhim> أَبَابِيلَ", "Wa arsala 'alayhim tayran ababil", "And He sent against them birds in flocks,", listOf(TajweedRuleType.TAFKHIM)),
            make(105, "Al-Fil", 4, "تَرْمِيهِم بِحِجَارَةٍ مِّن سِجِّيلٍ", "تَرْمِيهِم <ikhfa>بِحِجَارَةٍ</ikhfa> <idgham>مِّن</idgham> سِجِّيلٍ", "Tarmihim bi-hijaratim min sijjil", "Striking them with stones of hard clay,", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.IDGHAM)),
            make(105, "Al-Fil", 5, "فَجَعَلَهُمْ كَعَصْفٍ مَّأْكُولٍ", "فَجَعَلَهُمْ كَعَصْفٍ <idgham>مَّأْكُولٍ</idgham>", "Fa-ja'alahum ka-'asfim ma'kul", "And He made them like eaten straw.", listOf(TajweedRuleType.IDGHAM)),

            // ==================== SURAH 106: QURAYSH (4 Verses) ====================
            make(106, "Quraysh", 1, "لِإِيلَافِ قُرَيْشٍ", "لِإِيلَافِ <tafkhim>قُرَيْشٍ</tafkhim>", "Li-ilafi Quraysh", "For the accustomed security of Quraysh -", listOf(TajweedRuleType.TAFKHIM)),
            make(106, "Quraysh", 2, "إِيلَافِهِمْ رِحْلَةَ الشِّتَاءِ وَالصَّيْفِ", "إِيلَافِهِمْ رِحْلَةَ <hamzat_wasl>ال</hamzat_wasl>شِّتَ<madd>اءِ</madd> وَ<hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّيْفِ</tafkhim>", "Ilafihim rihlatash-shita'i was-sayf", "Their accustomed security [in] the caravan of winter and summer -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.TAFKHIM)),
            make(106, "Quraysh", 3, "فَلْيَعْبُدُوا رَبَّ هَٰذَا الْبَيْتِ", "فَلْيَعْبُدُوا رَبَّ هَٰذَا <hamzat_wasl>الْ</hamzat_wasl>بَيْتِ", "Fal-ya'budu rabba hadhal-bayt", "Let them worship the Lord of this House,", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(106, "Quraysh", 4, "الَّذِي أَطْعَمَهُم مِّن جُوعٍ وَآمَنَهُم مِّنْ خَوْفٍ", "<hamzat_wasl>الَّذِي</hamzat_wasl> <madd>أَ</madd><tafkhim>طْ</tafkhim><qalqalah>عَمَهُم</qalqalah> <idgham>مِّن</idgham> <ikhfa>جُوعٍ</ikhfa> <idgham>وَآمَنَهُم</idgham> مِّنْ خَوْفٍ", "Alladhi at'amahum min ju'iw wa amanahum min khawf", "Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD, TajweedRuleType.QALQALAH, TajweedRuleType.IDGHAM, TajweedRuleType.GHUNNAH)),

            // ==================== SURAH 107: AL-MA'UN (7 Verses) ====================
            make(107, "Al-Ma'un", 1, "أَرَأَيْتَ الَّذِي يُكَذِّبُ بِالدِّينِ", "أَرَأَيْتَ <hamzat_wasl>الَّذِي</hamzat_wasl> يُكَذِّبُ بِ<hamzat_wasl>ال</hamzat_wasl>دِّينِ", "Ara'aytal-ladhi yukadh-dhibu bid-din", "Have you seen the one who denies the Recompense?", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(107, "Al-Ma'un", 2, "فَذَٰلِكَ الَّذِي يَدُعُّ الْيَتِيمَ", "فَذَٰلِكَ <hamzat_wasl>الَّذِي</hamzat_wasl> يَدُعُّ <hamzat_wasl>الْ</hamzat_wasl>يَتِيمَ", "Fadhalikal-ladhi yadu''ul-yatim", "For that is the one who drives away the orphan", listOf(TajweedRuleType.HAMZAT_WASL)),
            make(107, "Al-Ma'un", 3, "وَلَا يَحُضُّ عَلَىٰ طَعَامِ الْمِسْكِينِ", "وَلَا يَحُ<tafkhim>ضُّ</tafkhim> عَلَىٰ <tafkhim>طَعَامِ</tafkhim> <hamzat_wasl>الْ</hamzat_wasl>مِسْكِينِ", "Wa la yahuddu 'ala ta'amil-miskin", "And does not encourage the feeding of the poor.", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(107, "Al-Ma'un", 4, "فَوَيْلٌ لِّلْمُصَلِّينَ", "فَوَيْلٌ <idgham>لِّلْمُ</idgham><tafkhim>صَلِّينَ</tafkhim>", "Fawaylul lil-musallin", "So woe to those who pray", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.TAFKHIM)),
            make(107, "Al-Ma'un", 5, "الَّذِينَ هُمْ عَن صَلَاتِهِمْ سَاهُونَ", "<hamzat_wasl>الَّذِينَ</hamzat_wasl> هُمْ عَن <ikhfa><tafkhim>صَلَاتِهِمْ</tafkhim></ikhfa> سَاهُونَ", "Alladhina hum 'an salatihim sahun", "[But] who are heedless of their prayer -", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(107, "Al-Ma'un", 6, "الَّذِينَ هُمْ يُرَاءُونَ", "<hamzat_wasl>الَّذِينَ</hamzat_wasl> هُمْ <madd>يُرَاءُونَ</madd>", "Alladhina hum yura'un", "Those who make a show [of their deeds]", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.MADD)),
            make(107, "Al-Ma'un", 7, "وَيَمْنَعُونَ الْمَاعُونَ", "وَيَمْنَعُونَ <hamzat_wasl>الْ</hamzat_wasl>مَاعُونَ", "Wa yamna'unal-ma'un", "And withhold [simple] assistance.", listOf(TajweedRuleType.HAMZAT_WASL)),

            // ==================== SURAH 108: AL-KAWTHAR (3 Verses) ====================
            make(108, "Al-Kawthar", 1, "إِنَّا أَعْطَيْنَاكَ الْكَوْثَرَ", "<ghunnah>إِنَّا</ghunnah> <madd>أَعْطَيْنَاكَ</madd> <hamzat_wasl>الْ</hamzat_wasl>كَوْثَرَ", "Inna a'taynakal-kawthar", "Indeed, We have granted you, [O Muhammad], al-Kawthar.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL)),
            make(108, "Al-Kawthar", 2, "فَصَلِّ لِرَبِّكَ وَانْحَرْ", "فَ<tafkhim>صَلِّ</tafkhim> لِرَبِّكَ وَ<hamzat_wasl>ا</hamzat_wasl>نْحَرْ", "Fasalli lirabbika wanhar", "So pray to your Lord and sacrifice [to Him alone].", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(108, "Al-Kawthar", 3, "إِنَّ شَانِئَكَ هُوَ الْأَبْتَرُ", "<ghunnah>إِنَّ</ghunnah> شَانِئَكَ هُوَ <hamzat_wasl>الْ</hamzat_wasl>أَ<qalqalah>بْتَرُ</qalqalah>", "Inna shani'aka huwal-abtar", "Indeed, your enemy is the one cut off.", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.QALQALAH)),

            // ==================== SURAH 109: AL-KAFIRUN (6 Verses) ====================
            make(109, "Al-Kafirun", 1, "قُلْ يَا أَيُّهَا الْكَافِرُونَ", "<tafkhim><qalqalah>قُلْ</qalqalah></tafkhim> يَا <madd>أَيُّهَا</madd> <hamzat_wasl>الْ</hamzat_wasl>كَافِرُونَ", "Qul ya ayyuhal-kafirun", "Say, 'O disbelievers,'", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.MADD, TajweedRuleType.HAMZAT_WASL)),
            make(109, "Al-Kafirun", 2, "لَا أَعْبُدُ مَا تَعْبُدُونَ", "لَا <madd>أَعْبُدُ</madd> مَا تَعْبُدُونَ", "La a'budu ma ta'budun", "'I do not worship what you worship.'", listOf(TajweedRuleType.MADD)),
            make(109, "Al-Kafirun", 3, "وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ", "وَلَا <madd>أَ</madd><ikhfa>نْتُمْ</ikhfa> عَابِدُونَ مَا <madd>أَعْبُدُ</madd>", "Wa la antum 'abiduna ma a'bud", "'Nor are you worshippers of what I worship.'", listOf(TajweedRuleType.MADD, TajweedRuleType.GHUNNAH)),
            make(109, "Al-Kafirun", 4, "وَلَا أَنَا عَابِدٌ مَّا عَبَدتُّمْ", "وَلَا <madd>أَنَا</madd> عَابِدٌ <idgham>مَّا</idgham> عَبَدتُّمْ", "Wa la ana 'abidum ma 'abattum", "'Nor will I be a worshipper of what you worship.'", listOf(TajweedRuleType.MADD, TajweedRuleType.IDGHAM)),
            make(109, "Al-Kafirun", 5, "وَلَا أَنتُمْ عَابِدُونَ مَا أَعْبُدُ", "وَلَا <madd>أَ</madd><ikhfa>نْتُمْ</ikhfa> عَابِدُونَ مَا <madd>أَعْبُدُ</madd>", "Wa la antum 'abiduna ma a'bud", "'Nor will you be worshippers of what I worship.'", listOf(TajweedRuleType.MADD, TajweedRuleType.GHUNNAH)),
            make(109, "Al-Kafirun", 6, "لَكُمْ دِينُكُمْ وَلِيَ دِينِ", "لَكُمْ دِينُكُمْ وَلِيَ دِينِ", "Lakum dinukum wa liya din", "'For you is your religion, and for me is my religion.'", emptyList()),

            // ==================== SURAH 110: AN-NASR (3 Verses) ====================
            make(110, "An-Nasr", 1, "إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ", "إِذَا <madd>جَاءَ</madd> <tafkhim>نَصْرُ</tafkhim> <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهِ</tafkhim> وَ<hamzat_wasl>الْ</hamzat_wasl>فَتْحُ", "Idha ja'a nasrul-lahi wal-fath", "When the victory of Allah has come and the conquest,", listOf(TajweedRuleType.MADD, TajweedRuleType.TAFKHIM, TajweedRuleType.HAMZAT_WASL)),
            make(110, "An-Nasr", 2, "وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا", "وَرَأَيْتَ <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاسَ</ghunnah> <qalqalah>يَدْخُلُونَ</qalqalah> فِي دِينِ <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهِ</tafkhim> أَفْوَاجًا", "Wa ra'aytan-nasa yadkhuluna fi dinil-lahi afwaja", "And you see the people entering into the religion of Allah in multitudes,", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH, TajweedRuleType.TAFKHIM)),
            make(110, "An-Nasr", 3, "فَسَبِّحْ بِحَمْدِ رَبِّكَ وَاسْتَغْفِرْهُ ۚ إِنَّهُ كَانَ تَوَّابًا", "فَسَبِّحْ بِحَمْدِ رَبِّكَ وَ<hamzat_wasl>ا</hamzat_wasl>سْتَغْفِرْهُ <ghunnah>إِنَّهُ</ghunnah> كَانَ تَوَّابًا", "Fasabbih bihamdi rabbika wastaghfirh, innahu kana tawwaba", "Then exalt [Him] with praise of your Lord and ask forgiveness of Him. Indeed, He is ever Accepting of repentance.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),

            // ==================== SURAH 111: AL-MASAD (5 Verses) ====================
            make(111, "Al-Masad", 1, "تَبَّتْ يَدَا أَبِي لَهَبٍ وَتَبَّ", "تَبَّتْ يَدَا <madd>أَبِي</madd> لَهَبٍ <idgham>وَتَبَّ</idgham>", "Tabbat yada abi lahabiw wa tabb", "May the hands of Abu Lahab be ruined, and ruined is he.", listOf(TajweedRuleType.MADD, TajweedRuleType.IDGHAM, TajweedRuleType.QALQALAH)),
            make(111, "Al-Masad", 2, "مَا أَغْنَىٰ عَنْهُ مَالُهُ وَمَا كَسَبَ", "مَا <madd>أَغْنَىٰ</madd> عَنْهُ مَالُهُ وَمَا كَسَ<qalqalah>بَ</qalqalah>", "Ma aghna 'anhu maluhu wa ma kasab", "His wealth will not avail him or that which he gained.", listOf(TajweedRuleType.MADD, TajweedRuleType.QALQALAH)),
            make(111, "Al-Masad", 3, "سَيَصْلَىٰ نَارًا ذَاتَ لَهَبٍ", "سَيَ<tafkhim>صْلَىٰ</tafkhim> نَارًا <ikhfa>ذَاتَ</ikhfa> لَهَ<qalqalah>بٍ</qalqalah>", "Sayasla naran dhata lahab", "He will [enter to] burn in a Fire of [blazing] flame", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),
            make(111, "Al-Masad", 4, "وَامْرَأَتُهُ حَمَّالَةَ الْحَطَبِ", "وَ<hamzat_wasl>ا</hamzat_wasl>مْرَأَتُهُ <ghunnah>حَمَّالَةَ</ghunnah> <hamzat_wasl>الْ</hamzat_wasl><tafkhim>حَطَبِ</tafkhim>", "Wamra'atuhu hammalatal-hatab", "And his wife [as well] - the carrier of firewood.", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM)),
            make(111, "Al-Masad", 5, "فِي جِيدِهَا حَبْلٌ مِّن مَّسَدٍ", "فِي جِيدِهَا <qalqalah>حَبْلٌ</qalqalah> <idgham>مِّن</idgham> <idgham>مَّسَدٍ</idgham>", "Fi jidiha hablum mim masad", "Around her neck is a rope of [twisted] fiber.", listOf(TajweedRuleType.QALQALAH, TajweedRuleType.IDGHAM)),

            // ==================== SURAH 112: AL-IKHLAS (4 Verses) ====================
            make(112, "Al-Ikhlas", 1, "قُلْ هُوَ اللَّهُ أَحَدٌ", "<tafkhim><qalqalah>قُلْ</qalqalah></tafkhim> هُوَ <hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> أَ<qalqalah>حَدٌ</qalqalah>", "Qul huwal-lahu ahad", "Say, 'He is Allah, [who is] One,'", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL)),
            make(112, "Al-Ikhlas", 2, "اللَّهُ الصَّمَدُ", "<hamzat_wasl>ال</hamzat_wasl><tafkhim>لَّهُ</tafkhim> <hamzat_wasl>ال</hamzat_wasl><tafkhim>صَّ</tafkhim><qalqalah>مَدُ</qalqalah>", "Allahus-samad", "'Allah, the Eternal Refuge.'", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(112, "Al-Ikhlas", 3, "لَمْ يَلِدْ وَلَمْ يُولَدْ", "لَمْ يَلِ<qalqalah>دْ</qalqalah> وَلَمْ يُولَ<qalqalah>دْ</qalqalah>", "Lam yalid wa lam yulad", "'He neither begets nor is born,'", listOf(TajweedRuleType.QALQALAH)),
            make(112, "Al-Ikhlas", 4, "وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ", "وَلَمْ يَكُن <idgham>لَّهُ</idgham> كُفُوًا أَ<qalqalah>حَدٌ</qalqalah>", "Wa lam yakul lahu kufuwan ahad", "'Nor is there to Him any equivalent.'", listOf(TajweedRuleType.IDGHAM, TajweedRuleType.QALQALAH)),

            // ==================== SURAH 113: AL-FALAQ (5 Verses) ====================
            make(113, "Al-Falaq", 1, "قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ", "<tafkhim><qalqalah>قُلْ</qalqalah></tafkhim> أَعُوذُ بِرَبِّ <hamzat_wasl>الْ</hamzat_wasl>فَلَ<tafkhim><qalqalah>قِ</qalqalah></tafkhim>", "Qul a'udhu birabbil-falaq", "Say, 'I seek refuge in the Lord of daybreak'", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL)),
            make(113, "Al-Falaq", 2, "مِن شَرِّ مَا خَلَقَ", "مِن <ikhfa>شَرِّ</ikhfa> مَا خَلَ<tafkhim><qalqalah>قَ</qalqalah></tafkhim>", "Min sharri ma khalaq", "From the evil of that which He created", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(113, "Al-Falaq", 3, "وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ", "وَمِن <ikhfa>شَرِّ</ikhfa> غَاسِقٍ إِذَا وَ<tafkhim>قَ</tafkhim><qalqalah>بَ</qalqalah>", "Wa min sharri ghasiqin idha waqab", "And from the evil of darkness when it settles", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(113, "Al-Falaq", 4, "وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ", "وَمِن <ikhfa>شَرِّ</ikhfa> <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّفَّاثَاتِ</ghunnah> فِي <hamzat_wasl>الْ</hamzat_wasl>عُ<tafkhim>قَ</tafkhim><qalqalah>دِ</qalqalah>", "Wa min sharrin-naffathati fil-'uqad", "And from the evil of the blowers in knots", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH)),
            make(113, "Al-Falaq", 5, "وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ", "وَمِن <ikhfa>شَرِّ</ikhfa> حَاسِدٍ إِذَا حَسَ<qalqalah>دَ</qalqalah>", "Wa min sharri hasidin idha hasad", "And from the evil of an envier when he envies.'", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.QALQALAH)),

            // ==================== SURAH 114: AN-NAS (6 Verses) ====================
            make(114, "An-Nas", 1, "قُلْ أَعُوذُ بِرَبِّ النَّاسِ", "<tafkhim><qalqalah>قُلْ</qalqalah></tafkhim> أَعُوذُ بِرَبِّ <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاسِ</ghunnah>", "Qul a'udhu birabbin-nas", "Say, 'I seek refuge in the Lord of mankind,'", listOf(TajweedRuleType.TAFKHIM, TajweedRuleType.QALQALAH, TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(114, "An-Nas", 2, "مَلِكِ النَّاسِ", "مَلِكِ <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاسِ</ghunnah>", "Malikin-nas", "'The Sovereign of mankind,'", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(114, "An-Nas", 3, "إِلَٰهِ النَّاسِ", "إِلَٰهِ <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاسِ</ghunnah>", "Ilahin-nas", "'The God of mankind,'", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH)),
            make(114, "An-Nas", 4, "مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ", "مِن <ikhfa>شَرِّ</ikhfa> <hamzat_wasl>الْ</hamzat_wasl>وَسْوَاسِ <hamzat_wasl>الْ</hamzat_wasl>خَ<ghunnah>نَّاسِ</ghunnah>", "Min sharril-waswasil-khannas", "'From the evil of the retreating whisperer -'", listOf(TajweedRuleType.GHUNNAH, TajweedRuleType.HAMZAT_WASL)),
            make(114, "An-Nas", 5, "الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ", "<hamzat_wasl>الَّذِي</hamzat_wasl> يُوَسْوِسُ فِي <tafkhim>صُ</tafkhim>دُورِ <hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاسِ</ghunnah>", "Alladhi yuwaswisu fi sudurin-nas", "'Who whispers [evil] into the breasts of mankind -'", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.TAFKHIM, TajweedRuleType.GHUNNAH)),
            make(114, "An-Nas", 6, "مِنَ الْجِنَّةِ وَالنَّاسِ", "مِنَ <hamzat_wasl>الْ</hamzat_wasl>جِ<ghunnah>نَّةِ</ghunnah> وَ<hamzat_wasl>ال</hamzat_wasl><ghunnah>نَّاسِ</ghunnah>", "Minal-jinnati wan-nas", "'From among the jinn and mankind.'", listOf(TajweedRuleType.HAMZAT_WASL, TajweedRuleType.GHUNNAH))
        )
    }
}
